// Keeps the events of this recipe, then builds the request(s) for HubSpot.
const WANTED = ["member.joined", "membership.started", "membership.cancelled"]
const out = []
for (const item of $input.all()) {
  const msg = item.json.body ?? item.json
  if (WANTED.length && !WANTED.includes(msg.event)) continue
  const u = msg.data.user ?? {}
  if (!u.email) continue
  const [first, ...rest] = (u.name ?? '').trim().split(/\s+/)
  const status = msg.event === 'membership.started' ? 'paid' : msg.event === 'membership.cancelled' ? 'ended' : 'free'
  out.push({ json: { method: 'POST', url: 'https://api.hubapi.com/crm/v3/objects/contacts/batch/upsert', body: { inputs: [{ id: u.email, idProperty: 'email', properties: { email: u.email, firstname: first ?? '', lastname: rest.join(' '), learnfloo_space: msg.space.slug, learnfloo_membership: status } }] } } })
}
return out
